def blocks(inp, sep):
    h=len(inp); w=len(inp[0])
    rsep=[r for r in range(h) if all(x==sep for x in inp[r])]
    csep=[c for c in range(w) if all(inp[r][c]==sep for r in range(h))]
    def ranges(n, seps):
        rs=[]; start=0
        for s in seps+[n]:
            if s>start: rs.append((start,s))
            start=s+1
        return rs
    return ranges(h,rsep), ranges(w,csep)
